python3 -I -c 'C="import sys,json,itertools as I,subprocess as S,tempfile,re\nfrom pathlib import Path\nQ=lambda:\"python3 -I -c %cC=%s;exec(C)%c \\\"$@\\\"\\n\"%(39,json.dumps(C),39)\nA=\"exact?|intro|assumption|rfl|constructor|apply?|aesop|simp_all\".split(\"|\")\ndef P(k,d):\n a=[]\n if not k:a=[\"intro p h\",\"exact h\"]\n while k:k,r=divmod(k-1,len(A));a.insert(0,A[r])\n return \"import Mathlib\\nset_option maxHeartbeats 0\\ntheorem uto : \"+(\"\u2200 p : Prop, p \u2192 p\" if d else \"RiemannHypothesis\")+\" := by\\n  \"+\"\\n  \".join(a)+\"\\n#print axioms uto\\n\"\ndef G(b):\n n=1\n for x in b:n=n*257+x+1\n return hex(n)[2:]\ndef D(g):\n n=int(g,16);a=[]\n while n>1:n,x=divmod(n-1,257);a.append(x)\n assert n==1;return bytes(a[::-1])\ndef ok(s):\n a=repr(\"uto\");m=re.fullmatch(a+r\" depends on axioms: \\[([^\\]]*)\\]\",s.strip())\n return set(m[1].replace(\",\",\" \").split())<=set(\"propext Classical.choice Quot.sound\".split()) if m else s.strip()==a+\" does not depend on any axioms\"\nm,*v=sys.argv[1:] or [\"self\"]\nif m==\"self\":print(Q(),end=\"\")\nelif m==\"encode\":print(G(Q().encode()))\nelif m==\"decode\":sys.stdout.buffer.write(D(v[0]))\nelif m==\"emit\":k=int(v[0]);assert k>0;print(P(k,False),end=\"\")\nelif m in (\"search\",\"demo\"):\n f=Path(v[0]);b=int(v[1]);assert b>=0\n assert not f.exists()\n with tempfile.TemporaryDirectory(dir=\".\") as t:\n  p=Path(t)/\"C.lean\"\n  def run(z,n):\n   p.write_bytes(z.encode())\n   try:r=S.run([\"lake\",\"env\",\"lean\",str(p)],capture_output=True,text=True,timeout=n)\n   except FileNotFoundError:sys.exit(\"NOT_CHECKED: lake missing\")\n   except S.TimeoutExpired:return False\n   return not r.returncode and ok(r.stdout)\n  if not run(P(0,True),120):sys.exit(\"NOT_CHECKED: smoke failed\")\n  for n in I.count(1):\n   if b and n>b:sys.exit(\"UNKNOWN\")\n   for k in range(0 if m==\"demo\" else 1,n+1):\n    z=P(k,m==\"demo\")\n    if run(z,n+60):\n     with f.open(\"xb\") as w:w.write(z.encode())\n     print(\"LEAN_ACCEPTED\",k,n);sys.exit()";exec(C)' "$@"
